22 inline Vector2 Rectangle::Location() const noexcept
23 {
24     return Vector2(float(x), float(y));
25 }
26 
27 inline Vector2 Rectangle::Center() const noexcept
28 {
29     return Vector2(float(x) + (float(width) / 2.f), float(y) + (float(height) / 2.f));
30 }
31 
32 inline bool Rectangle::Contains(const Vector2& point) const noexcept
33 {
34     return (float(x) <= point.x) && (point.x < float(x + width)) && (float(y) <= point.y) && (point.y < float(y + height));
35 }
36 
37 inline void Rectangle::Inflate(long horizAmount, long vertAmount) noexcept
38 {
39     x -= horizAmount;
40     y -= vertAmount;
41     width += horizAmount;
42     height += vertAmount;
43 }
