49 inline Rectangle Rectangle::Intersect(const Rectangle& ra, const Rectangle& rb) noexcept
50 {
51     const long righta = ra.x + ra.width;
52     const long rightb = rb.x + rb.width;
53 
54     const long bottoma = ra.y + ra.height;
55     const long bottomb = rb.y + rb.height;
56 
57     const long maxX = ra.x > rb.x ? ra.x : rb.x;
58     const long maxY = ra.y > rb.y ? ra.y : rb.y;
59 
60     const long minRight = righta < rightb ? righta : rightb;
61     const long minBottom = bottoma < bottomb ? bottoma : bottomb;
62 
63     Rectangle result;
64 
65     if ((minRight > maxX) && (minBottom > maxY))
66     {
67         result.x = maxX;
68         result.y = maxY;
69         result.width = minRight - maxX;
70         result.height = minBottom - maxY;
71     }
72     else
73     {
74         result.x = 0;
75         result.y = 0;
76         result.width = 0;
77         result.height = 0;
78     }
79 
80     return result;
81 }
82 
83 inline RECT Rectangle::Intersect(const RECT& rcta, const RECT& rctb) noexcept
84 {
85     const long maxX = rcta.left > rctb.left ? rcta.left : rctb.left;
86     const long maxY = rcta.top > rctb.top ? rcta.top : rctb.top;
87 
88     const long minRight = rcta.right < rctb.right ? rcta.right : rctb.right;
89     const long minBottom = rcta.bottom < rctb.bottom ? rcta.bottom : rctb.bottom;
90 
91     RECT result;
92 
93     if ((minRight > maxX) && (minBottom > maxY))
94     {
95         result.left = maxX;
96         result.top = maxY;
97         result.right = minRight;
98         result.bottom = minBottom;
99     }
100     else
101     {
102         result.left = 0;
103         result.top = 0;
104         result.right = 0;
105         result.bottom = 0;
106     }
107 
108     return result;
109 }
