111 inline Rectangle Rectangle::Union(const Rectangle& ra, const Rectangle& rb) noexcept
112 {
113     const long righta = ra.x + ra.width;
114     const long rightb = rb.x + rb.width;
115 
116     const long bottoma = ra.y + ra.height;
117     const long bottomb = rb.y + rb.height;
118 
119     const int minX = ra.x < rb.x ? ra.x : rb.x;
120     const int minY = ra.y < rb.y ? ra.y : rb.y;
121 
122     const int maxRight = righta > rightb ? righta : rightb;
123     const int maxBottom = bottoma > bottomb ? bottoma : bottomb;
124 
125     Rectangle result;
126     result.x = minX;
127     result.y = minY;
128     result.width = maxRight - minX;
129     result.height = maxBottom - minY;
130     return result;
131 }
132 
133 inline RECT Rectangle::Union(const RECT& rcta, const RECT& rctb) noexcept
134 {
135     RECT result;
136     result.left = rcta.left < rctb.left ? rcta.left : rctb.left;
137     result.top = rcta.top < rctb.top ? rcta.top : rctb.top;
138     result.right = rcta.right > rctb.right ? rcta.right : rctb.right;
139     result.bottom = rcta.bottom > rctb.bottom ? rcta.bottom : rctb.bottom;
140     return result;
141 }
