482 inline void Vector2::SmoothStep(const Vector2& v1, const Vector2& v2, float t, Vector2& result) noexcept
483 {
484     using namespace DirectX;
485     t = (t > 1.0f) ? 1.0f : ((t < 0.0f) ? 0.0f : t);  // Clamp value to 0 to 1
486     t = t * t*(3.f - 2.f*t);
487     const XMVECTOR x1 = XMLoadFloat2(&v1);
488     const XMVECTOR x2 = XMLoadFloat2(&v2);
489     const XMVECTOR X = XMVectorLerp(x1, x2, t);
490     XMStoreFloat2(&result, X);
491 }
