1071 inline void Vector3::SmoothStep(const Vector3& v1, const Vector3& v2, float t, Vector3& result) noexcept
1072 {
1073     using namespace DirectX;
1074     t = (t > 1.0f) ? 1.0f : ((t < 0.0f) ? 0.0f : t);  // Clamp value to 0 to 1
1075     t = t * t*(3.f - 2.f*t);
1076     const XMVECTOR x1 = XMLoadFloat3(&v1);
1077     const XMVECTOR x2 = XMLoadFloat3(&v2);
1078     const XMVECTOR X = XMVectorLerp(x1, x2, t);
1079     XMStoreFloat3(&result, X);
1080 }
