1662 inline void Vector4::SmoothStep(const Vector4& v1, const Vector4& v2, float t, Vector4& result) noexcept
1663 {
1664     using namespace DirectX;
1665     t = (t > 1.0f) ? 1.0f : ((t < 0.0f) ? 0.0f : t);  // Clamp value to 0 to 1
1666     t = t * t*(3.f - 2.f*t);
1667     const XMVECTOR x1 = XMLoadFloat4(&v1);
1668     const XMVECTOR x2 = XMLoadFloat4(&v2);
1669     const XMVECTOR X = XMVectorLerp(x1, x2, t);
1670     XMStoreFloat4(&result, X);
1671 }
