1911 inline bool Matrix::operator == (const Matrix& M) const noexcept
1912 {
1913     using namespace DirectX;
1914     const XMVECTOR x1 = XMLoadFloat4(reinterpret_cast<const XMFLOAT4*>(&_11));
1915     const XMVECTOR x2 = XMLoadFloat4(reinterpret_cast<const XMFLOAT4*>(&_21));
1916     const XMVECTOR x3 = XMLoadFloat4(reinterpret_cast<const XMFLOAT4*>(&_31));
1917     const XMVECTOR x4 = XMLoadFloat4(reinterpret_cast<const XMFLOAT4*>(&_41));
1918 
1919     const XMVECTOR y1 = XMLoadFloat4(reinterpret_cast<const XMFLOAT4*>(&M._11));
1920     const XMVECTOR y2 = XMLoadFloat4(reinterpret_cast<const XMFLOAT4*>(&M._21));
1921     const XMVECTOR y3 = XMLoadFloat4(reinterpret_cast<const XMFLOAT4*>(&M._31));
1922     const XMVECTOR y4 = XMLoadFloat4(reinterpret_cast<const XMFLOAT4*>(&M._41));
1923 
1924     return (XMVector4Equal(x1, y1)
1925         && XMVector4Equal(x2, y2)
1926         && XMVector4Equal(x3, y3)
1927         && XMVector4Equal(x4, y4)) != 0;
1928 }
