2363 inline Vector3 Matrix::ToEuler() const noexcept
2364 {
2365     const float cy = sqrtf(_33 * _33 + _31 * _31);
2366     const float cx = atan2f(-_32, cy);
2367     if (cy > 16.f * FLT_EPSILON)
2368     {
2369         return Vector3(cx, atan2f(_31, _33), atan2f(_12, _22));
2370     }
2371     else
2372     {
2373         return Vector3(cx, 0.f, atan2f(-_21, _11));
2374     }
2375 }
