2381 _Use_decl_annotations_
2382 inline Matrix Matrix::CreateBillboard(
2383     const Vector3& object,
2384     const Vector3& cameraPosition,
2385     const Vector3& cameraUp,
2386     const Vector3* cameraForward) noexcept
2387 {
2388     using namespace DirectX;
2389     const XMVECTOR O = XMLoadFloat3(&object);
2390     const XMVECTOR C = XMLoadFloat3(&cameraPosition);
2391     XMVECTOR Z = XMVectorSubtract(O, C);
2392 
2393     const XMVECTOR N = XMVector3LengthSq(Z);
2394     if (XMVector3Less(N, g_XMEpsilon))
2395     {
2396         if (cameraForward)
2397         {
2398             const XMVECTOR F = XMLoadFloat3(cameraForward);
2399             Z = XMVectorNegate(F);
2400         }
2401         else
2402             Z = g_XMNegIdentityR2;
2403     }
2404     else
2405     {
2406         Z = XMVector3Normalize(Z);
2407     }
2408 
2409     const XMVECTOR up = XMLoadFloat3(&cameraUp);
2410     XMVECTOR X = XMVector3Cross(up, Z);
2411     X = XMVector3Normalize(X);
2412 
2413     const XMVECTOR Y = XMVector3Cross(Z, X);
2414 
2415     XMMATRIX M;
2416     M.r[0] = X;
2417     M.r[1] = Y;
2418     M.r[2] = Z;
2419     M.r[3] = XMVectorSetW(O, 1.f);
2420 
2421     Matrix R;
2422     XMStoreFloat4x4(&R, M);
2423     return R;
2424 }
2425 
2426 _Use_decl_annotations_
2427 inline Matrix Matrix::CreateConstrainedBillboard(
2428     const Vector3& object,
2429     const Vector3& cameraPosition,
2430     const Vector3& rotateAxis,
2431     const Vector3* cameraForward,
2432     const Vector3* objectForward) noexcept
2433 {
2434     using namespace DirectX;
2435 
2436     static const XMVECTORF32 s_minAngle = { { { 0.99825467075f, 0.99825467075f, 0.99825467075f, 0.99825467075f } } }; // 1.0 - XMConvertToRadians( 0.1f );
2437 
2438     const XMVECTOR O = XMLoadFloat3(&object);
2439     const XMVECTOR C = XMLoadFloat3(&cameraPosition);
2440     XMVECTOR faceDir = XMVectorSubtract(O, C);
2441 
2442     const XMVECTOR N = XMVector3LengthSq(faceDir);
2443     if (XMVector3Less(N, g_XMEpsilon))
2444     {
2445         if (cameraForward)
2446         {
2447             const XMVECTOR F = XMLoadFloat3(cameraForward);
2448             faceDir = XMVectorNegate(F);
2449         }
2450         else
2451             faceDir = g_XMNegIdentityR2;
2452     }
2453     else
2454     {
2455         faceDir = XMVector3Normalize(faceDir);
2456     }
2457 
2458     const XMVECTOR Y = XMLoadFloat3(&rotateAxis);
2459     XMVECTOR X, Z;
2460 
2461     XMVECTOR dot = XMVectorAbs(XMVector3Dot(Y, faceDir));
2462     if (XMVector3Greater(dot, s_minAngle))
2463     {
2464         if (objectForward)
2465         {
2466             Z = XMLoadFloat3(objectForward);
2467             dot = XMVectorAbs(XMVector3Dot(Y, Z));
2468             if (XMVector3Greater(dot, s_minAngle))
2469             {
2470                 dot = XMVectorAbs(XMVector3Dot(Y, g_XMNegIdentityR2));
2471                 Z = (XMVector3Greater(dot, s_minAngle)) ? g_XMIdentityR0 : g_XMNegIdentityR2;
2472             }
2473         }
2474         else
2475         {
2476             dot = XMVectorAbs(XMVector3Dot(Y, g_XMNegIdentityR2));
2477             Z = (XMVector3Greater(dot, s_minAngle)) ? g_XMIdentityR0 : g_XMNegIdentityR2;
2478         }
2479 
2480         X = XMVector3Cross(Y, Z);
2481         X = XMVector3Normalize(X);
2482 
2483         Z = XMVector3Cross(X, Y);
2484         Z = XMVector3Normalize(Z);
2485     }
2486     else
2487     {
2488         X = XMVector3Cross(Y, faceDir);
2489         X = XMVector3Normalize(X);
2490 
2491         Z = XMVector3Cross(X, Y);
2492         Z = XMVector3Normalize(Z);
2493     }
2494 
2495     XMMATRIX M;
2496     M.r[0] = X;
2497     M.r[1] = Y;
2498     M.r[2] = Z;
2499     M.r[3] = XMVectorSetW(O, 1.f);
2500 
2501     Matrix R;
2502     XMStoreFloat4x4(&R, M);
2503     return R;
2504 }
