2630 inline Matrix Matrix::CreateWorld(const Vector3& position, const Vector3& forward, const Vector3& up) noexcept
2631 {
2632     using namespace DirectX;
2633     const XMVECTOR zaxis = XMVector3Normalize(XMVectorNegate(XMLoadFloat3(&forward)));
2634     XMVECTOR yaxis = XMLoadFloat3(&up);
2635     const XMVECTOR xaxis = XMVector3Normalize(XMVector3Cross(yaxis, zaxis));
2636     yaxis = XMVector3Cross(zaxis, xaxis);
2637 
2638     Matrix R;
2639     XMStoreFloat3(reinterpret_cast<XMFLOAT3*>(&R._11), xaxis);
2640     XMStoreFloat3(reinterpret_cast<XMFLOAT3*>(&R._21), yaxis);
2641     XMStoreFloat3(reinterpret_cast<XMFLOAT3*>(&R._31), zaxis);
2642     R._14 = R._24 = R._34 = 0.f;
2643     R._41 = position.x; R._42 = position.y; R._43 = position.z;
2644     R._44 = 1.f;
2645     return R;
2646 }
