3123 inline Vector3 Quaternion::ToEuler() const noexcept
3124 {
3125     const float xx = x * x;
3126     const float yy = y * y;
3127     const float zz = z * z;
3128 
3129     const float m31 = 2.f * x * z + 2.f * y * w;
3130     const float m32 = 2.f * y * z - 2.f * x * w;
3131     const float m33 = 1.f - 2.f * xx - 2.f * yy;
3132 
3133     const float cy = sqrtf(m33 * m33 + m31 * m31);
3134     const float cx = atan2f(-m32, cy);
3135     if (cy > 16.f * FLT_EPSILON)
3136     {
3137         const float m12 = 2.f * x * y + 2.f * z * w;
3138         const float m22 = 1.f - 2.f * xx - 2.f * zz;
3139 
3140         return Vector3(cx, atan2f(m31, m33), atan2f(m12, m22));
3141     }
3142     else
3143     {
3144         const float m11 = 1.f - 2.f * yy - 2.f * zz;
3145         const float m21 = 2.f * x * y - 2.f * z * w;
3146 
3147         return Vector3(cx, 0.f, atan2f(-m21, m11));
3148     }
3149 }
