3191 inline void Quaternion::Lerp(const Quaternion& q1, const Quaternion& q2, float t, Quaternion& result) noexcept
3192 {
3193     using namespace DirectX;
3194     const XMVECTOR Q0 = XMLoadFloat4(&q1);
3195     const XMVECTOR Q1 = XMLoadFloat4(&q2);
3196 
3197     const XMVECTOR dot = XMVector4Dot(Q0, Q1);
3198 
3199     XMVECTOR R;
3200     if (XMVector4GreaterOrEqual(dot, XMVectorZero()))
3201     {
3202         R = XMVectorLerp(Q0, Q1, t);
3203     }
3204     else
3205     {
3206         const XMVECTOR tv = XMVectorReplicate(t);
3207         const XMVECTOR t1v = XMVectorReplicate(1.f - t);
3208         const XMVECTOR X0 = XMVectorMultiply(Q0, t1v);
3209         const XMVECTOR X1 = XMVectorMultiply(Q1, tv);
3210         R = XMVectorSubtract(X0, X1);
3211     }
3212 
3213     XMStoreFloat4(&result, XMQuaternionNormalize(R));
3214 }
3215 
3216 inline Quaternion Quaternion::Lerp(const Quaternion& q1, const Quaternion& q2, float t) noexcept
3217 {
3218     using namespace DirectX;
3219     const XMVECTOR Q0 = XMLoadFloat4(&q1);
3220     const XMVECTOR Q1 = XMLoadFloat4(&q2);
3221 
3222     const XMVECTOR dot = XMVector4Dot(Q0, Q1);
3223 
3224     XMVECTOR R;
3225     if (XMVector4GreaterOrEqual(dot, XMVectorZero()))
3226     {
3227         R = XMVectorLerp(Q0, Q1, t);
3228     }
3229     else
3230     {
3231         const XMVECTOR tv = XMVectorReplicate(t);
3232         const XMVECTOR t1v = XMVectorReplicate(1.f - t);
3233         const XMVECTOR X0 = XMVectorMultiply(Q0, t1v);
3234         const XMVECTOR X1 = XMVectorMultiply(Q1, tv);
3235         R = XMVectorSubtract(X0, X1);
3236     }
3237 
3238     Quaternion result;
3239     XMStoreFloat4(&result, XMQuaternionNormalize(R));
3240     return result;
3241 }
