3295 inline float Quaternion::Angle(const Quaternion& q1, const Quaternion& q2) noexcept
3296 {
3297     using namespace DirectX;
3298     const XMVECTOR Q0 = XMLoadFloat4(&q1);
3299     const XMVECTOR Q1 = XMLoadFloat4(&q2);
3300 
3301     // We can use the conjugate here instead of inverse assuming q1 & q2 are normalized.
3302     XMVECTOR R = XMQuaternionMultiply(XMQuaternionConjugate(Q0), Q1);
3303 
3304     const float rs = XMVectorGetW(R);
3305     R = XMVector3Length(R);
3306     return 2.f * atan2f(XMVectorGetX(R), rs);
3307 }
