3642 inline bool Ray::operator == (const Ray& r) const noexcept
3643 {
3644     using namespace DirectX;
3645     const XMVECTOR r1p = XMLoadFloat3(&position);
3646     const XMVECTOR r2p = XMLoadFloat3(&r.position);
3647     const XMVECTOR r1d = XMLoadFloat3(&direction);
3648     const XMVECTOR r2d = XMLoadFloat3(&r.direction);
3649     return XMVector3Equal(r1p, r2p) && XMVector3Equal(r1d, r2d);
3650 }
3651 
3652 inline bool Ray::operator != (const Ray& r) const noexcept
3653 {
3654     using namespace DirectX;
3655     const XMVECTOR r1p = XMLoadFloat3(&position);
3656     const XMVECTOR r2p = XMLoadFloat3(&r.position);
3657     const XMVECTOR r1d = XMLoadFloat3(&direction);
3658     const XMVECTOR r2d = XMLoadFloat3(&r.direction);
3659     return XMVector3NotEqual(r1p, r2p) && XMVector3NotEqual(r1d, r2d);
3660 }
