3679 }
3680 
3681 inline bool Ray::Intersects(const Plane& plane, _Out_ float& Dist) const noexcept
3682 {
3683     using namespace DirectX;
3684 
3685     const XMVECTOR p = XMLoadFloat4(&plane);
3686     const XMVECTOR dir = XMLoadFloat3(&direction);
3687 
3688     const XMVECTOR nd = XMPlaneDotNormal(p, dir);
3689 
3690     if (XMVector3LessOrEqual(XMVectorAbs(nd), g_RayEpsilon))
3691     {
3692         Dist = 0.f;
3693         return false;
3694     }
3695     else
3696     {
3697         // t = -(dot(n,origin) + D) / dot(n,dir)
3698         const XMVECTOR pos = XMLoadFloat3(&position);
3699         XMVECTOR v = XMPlaneDotNormal(p, pos);
3700         v = XMVectorAdd(v, XMVectorSplatW(p));
3701         v = XMVectorDivide(v, nd);
3702         float dist = -XMVectorGetX(v);
3703         if (dist < 0)
3704         {
3705             Dist = 0.f;
3706             return false;
3707         }
3708         else
3709         {
3710             Dist = dist;
3711             return true;
3712         }
3713     }
3714 }
