3727 #if (__cplusplus < 202002L)
3728 inline bool Viewport::operator == (const Viewport& vp) const noexcept
3729 {
3730     return (x == vp.x && y == vp.y
3731         && width == vp.width && height == vp.height
3732         && minDepth == vp.minDepth && maxDepth == vp.maxDepth);
3733 }
3734 
3735 inline bool Viewport::operator != (const Viewport& vp) const noexcept
3736 {
3737     return (x != vp.x || y != vp.y
3738         || width != vp.width || height != vp.height
3739         || minDepth != vp.minDepth || maxDepth != vp.maxDepth);
3740 }
3741 #endif
