3747 inline Viewport& Viewport::operator= (const RECT& rct) noexcept
3748 {
3749     x = float(rct.left); y = float(rct.top);
3750     width = float(rct.right - rct.left);
3751     height = float(rct.bottom - rct.top);
3752     minDepth = 0.f; maxDepth = 1.f;
3753     return *this;
3754 }
3755 
3756 #if defined(__d3d11_h__) || defined(__d3d11_x_h__)
3757 inline Viewport& Viewport::operator= (const D3D11_VIEWPORT& vp) noexcept
3758 {
3759     x = vp.TopLeftX; y = vp.TopLeftY;
3760     width = vp.Width; height = vp.Height;
3761     minDepth = vp.MinDepth; maxDepth = vp.MaxDepth;
3762     return *this;
3763 }
3764 #endif
