3766 #if defined(__d3d12_h__) || defined(__d3d12_x_h__) || defined(__XBOX_D3D12_X__)
3767 inline Viewport& Viewport::operator= (const D3D12_VIEWPORT& vp) noexcept
3768 {
3769     x = vp.TopLeftX; y = vp.TopLeftY;
3770     width = vp.Width; height = vp.Height;
